-- Schema for skopos
-- Uses UUIDv7-compatible text identifiers generated by the application.
CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    workspace TEXT NOT NULL,
    status TEXT NOT NULL,
    started_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS agents (
    id TEXT PRIMARY KEY,
    type TEXT NOT NULL,
    workspace TEXT NOT NULL,
    first_seen_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS agent_states (
    session_id TEXT NOT NULL,
    agent_id TEXT NOT NULL,
    agent_type TEXT NOT NULL,
    workspace TEXT NOT NULL,
    status TEXT NOT NULL,
    progress INTEGER,
    step_current INTEGER,
    step_total INTEGER,
    message TEXT NOT NULL DEFAULT '',
    snippet TEXT NOT NULL DEFAULT '',
    metadata TEXT NOT NULL DEFAULT '{}',
    updated_at TEXT NOT NULL,
    original_status TEXT,
    stuck_at TEXT,
    git_branch TEXT,
    PRIMARY KEY (session_id, agent_id),
    FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    agent_id TEXT NOT NULL,
    agent_type TEXT NOT NULL,
    workspace TEXT NOT NULL,
    status TEXT NOT NULL,
    progress INTEGER,
    step_current INTEGER,
    step_total INTEGER,
    message TEXT NOT NULL DEFAULT '',
    snippet TEXT NOT NULL DEFAULT '',
    metadata TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL,
    FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_sessions_updated_at ON sessions(updated_at DESC);
-- Sessions listed (and deleted) per workspace.
CREATE INDEX IF NOT EXISTS idx_sessions_workspace ON sessions(workspace, updated_at DESC);
-- The health ticker's orphan sweep (every minute, under the write lock) only
-- looks at live sessions; the WHERE must match its query's term exactly.
CREATE INDEX IF NOT EXISTS idx_sessions_live ON sessions(updated_at)
    WHERE status NOT IN ('succeeded', 'failed', 'cancelled', 'orphaned');
CREATE INDEX IF NOT EXISTS idx_agent_states_session_id ON agent_states(session_id);
CREATE INDEX IF NOT EXISTS idx_agent_states_health ON agent_states(status, updated_at, stuck_at);
-- The active-agents list (same term as its query).
CREATE INDEX IF NOT EXISTS idx_agent_states_active ON agent_states(updated_at DESC)
    WHERE status NOT IN ('succeeded', 'failed', 'cancelled', 'stuck', 'orphaned');
CREATE INDEX IF NOT EXISTS idx_events_session_created_at ON events(session_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_agent_created_at ON events(agent_id, created_at DESC);
-- Retention cleanup deletes by created_at alone: without this index every run
-- scanned the whole table while holding the write lock.
CREATE INDEX IF NOT EXISTS idx_events_created_at ON events(created_at);

CREATE TABLE IF NOT EXISTS blackboard_entries (
    id              TEXT PRIMARY KEY,
    workspace_id    TEXT,
    scope           TEXT NOT NULL,
    branch_name     TEXT,
    session_id      TEXT,
    entry_type      TEXT NOT NULL,
    title           TEXT NOT NULL,
    content         TEXT NOT NULL DEFAULT '',
    code_ref        TEXT,
    author_agent_id TEXT NOT NULL,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_blackboard_workspace ON blackboard_entries(workspace_id, scope, branch_name);
CREATE INDEX IF NOT EXISTS idx_blackboard_scope   ON blackboard_entries(scope, branch_name);
CREATE INDEX IF NOT EXISTS idx_blackboard_session ON blackboard_entries(session_id);
CREATE INDEX IF NOT EXISTS idx_blackboard_type    ON blackboard_entries(entry_type);

CREATE TABLE IF NOT EXISTS plans (
    id              TEXT PRIMARY KEY,
    workspace_id    TEXT,
    name            TEXT NOT NULL,
    branch_name     TEXT,
    description     TEXT NOT NULL DEFAULT '',
    status          TEXT NOT NULL DEFAULT 'active',
    author_agent_id TEXT NOT NULL,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS plan_items (
    id                  TEXT PRIMARY KEY,
    plan_id             TEXT NOT NULL,
    title               TEXT NOT NULL,
    description         TEXT NOT NULL DEFAULT '',
    phase               TEXT,
    status              TEXT NOT NULL DEFAULT 'pending',
    position            INTEGER NOT NULL DEFAULT 0,
    claimed_by_agent_id TEXT,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    FOREIGN KEY (plan_id) REFERENCES plans(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS plan_item_dependencies (
    item_id           TEXT NOT NULL,
    depends_on_item_id TEXT NOT NULL,
    PRIMARY KEY (item_id, depends_on_item_id),
    FOREIGN KEY (item_id) REFERENCES plan_items(id) ON DELETE CASCADE,
    FOREIGN KEY (depends_on_item_id) REFERENCES plan_items(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS plan_dependencies (
    plan_id             TEXT NOT NULL,
    depends_on_plan_id  TEXT NOT NULL,
    PRIMARY KEY (plan_id, depends_on_plan_id),
    FOREIGN KEY (plan_id) REFERENCES plans(id) ON DELETE CASCADE,
    FOREIGN KEY (depends_on_plan_id) REFERENCES plans(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_plans_workspace ON plans(workspace_id, branch_name);
CREATE INDEX IF NOT EXISTS idx_plans_branch    ON plans(branch_name);
CREATE INDEX IF NOT EXISTS idx_plan_items_plan ON plan_items(plan_id, position);
CREATE INDEX IF NOT EXISTS idx_item_deps_item  ON plan_item_dependencies(item_id);
CREATE INDEX IF NOT EXISTS idx_item_deps_dep   ON plan_item_dependencies(depends_on_item_id);
CREATE INDEX IF NOT EXISTS idx_plan_deps_plan  ON plan_dependencies(plan_id);
CREATE INDEX IF NOT EXISTS idx_plan_deps_dep   ON plan_dependencies(depends_on_plan_id);

-- Plan revisions (docs/design/agent-pipeline.md §4): immutable snapshots of a
-- plan's steps plus the base commit the planner read. Interactive plans keep
-- working unchanged (no revisions, no gate); workflow plans snapshot when the
-- plan is ready for review. An approved revision is LOCKED: only step status
-- (and claims) may change afterwards — any structural deviation becomes a new
-- revision (amendment) and the item returns to awaiting_approval.
CREATE TABLE IF NOT EXISTS plan_revisions (
    id            TEXT PRIMARY KEY,
    plan_id       TEXT NOT NULL REFERENCES plans(id) ON DELETE CASCADE,
    workspace_id  TEXT NOT NULL DEFAULT '',
    revision_no   INTEGER NOT NULL,
    steps_json    TEXT NOT NULL,
    content_hash  TEXT NOT NULL,
    base_sha      TEXT NOT NULL DEFAULT '',
    created_at    TEXT NOT NULL,
    locked_at     TEXT
);

CREATE INDEX IF NOT EXISTS idx_plan_revisions_plan ON plan_revisions(plan_id, revision_no DESC);

-- Approvals (docs/design/agent-pipeline.md §4): every human decision names an
-- immutable subject — a plan revision plus its base commit (gate=plan) or a
-- branch head (gate=review). Append-only; a new commit after a review
-- approval makes that review stale by comparison, not by deletion.
CREATE TABLE IF NOT EXISTS approvals (
    id           TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    item_id      TEXT NOT NULL,
    gate         TEXT NOT NULL,
    subject      TEXT NOT NULL,
    decision     TEXT NOT NULL,
    actor        TEXT NOT NULL,
    actor_key_id TEXT,
    via          TEXT NOT NULL DEFAULT '',
    notes        TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_approvals_item ON approvals(item_id, created_at);

CREATE TABLE IF NOT EXISTS workspaces (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL DEFAULT '',
    git_url    TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);

-- Inbox: workspace-scoped captures of unprocessed work (docs/design/inbox.md).
-- Content is raw markdown (source of truth); tags is a normalized JSON array.
-- Priority is a partial order: NULL = unprioritized (always sorted after
-- prioritized items); smaller values first. workspace_id is NULL for unfiled
-- captures (root-only visibility until the item is filed).
CREATE TABLE IF NOT EXISTS inbox_items (
    id                  TEXT PRIMARY KEY,
    workspace_id        TEXT,
    title               TEXT NOT NULL,
    content             TEXT NOT NULL DEFAULT '',
    tags                TEXT NOT NULL DEFAULT '[]',
    status              TEXT NOT NULL DEFAULT 'open',
    priority            INTEGER,
    claimed_by_agent_id TEXT,
    author_agent_id     TEXT NOT NULL,
    plan_id             TEXT,
    slack_thread_ts     TEXT NOT NULL DEFAULT '',   -- Slack relay: the item's notification thread root
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_inbox_workspace ON inbox_items(workspace_id, status);
CREATE INDEX IF NOT EXISTS idx_inbox_plan ON inbox_items(plan_id);

-- API keys: scoped credentials replacing the single shared root key
-- (docs/design/api-keys.md). Plaintext keys are never stored — only the
-- SHA-256 hash and a display prefix. Revocation is soft (audit trail).
-- approver marks keys that may perform human-only workflow actions
-- (docs/design/agent-pipeline.md §2); root implies it, and agent/worker
-- keys never get it.
CREATE TABLE IF NOT EXISTS api_keys (
    id             TEXT PRIMARY KEY,
    name           TEXT NOT NULL,
    key_hash       TEXT NOT NULL UNIQUE,
    key_prefix     TEXT NOT NULL,
    all_workspaces INTEGER NOT NULL DEFAULT 0,
    approver       INTEGER NOT NULL DEFAULT 0,
    -- key capabilities: JSON array of surfaces/areas, NULL = full access
    capabilities   TEXT CHECK (capabilities IS NULL OR json_valid(capabilities)),
    created_at     TEXT NOT NULL,
    last_used_at   TEXT,
    revoked_at     TEXT
);

CREATE INDEX IF NOT EXISTS idx_api_keys_hash ON api_keys(key_hash);

CREATE TABLE IF NOT EXISTS api_key_workspaces (
    api_key_id   TEXT NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE,
    workspace_id TEXT NOT NULL,
    PRIMARY KEY (api_key_id, workspace_id)
);

-- Workspace groups: a key's scope is its explicit workspaces plus its groups'
-- members plus registered workspaces matching its groups' patterns
-- (docs/design/agent-pipeline.md §3). Patterns are Go path.Match — `*` matches
-- one path segment and never crosses `/`. Group members must be registered
-- workspaces (validated at write time); pattern matches resolve against the
-- registry at lookup time, so new repos are picked up on the next request.
CREATE TABLE IF NOT EXISTS workspace_groups (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    created_at  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS workspace_group_members (
    group_id     TEXT NOT NULL REFERENCES workspace_groups(id) ON DELETE CASCADE,
    workspace_id TEXT NOT NULL,
    PRIMARY KEY (group_id, workspace_id)
);

CREATE TABLE IF NOT EXISTS workspace_group_patterns (
    group_id TEXT NOT NULL REFERENCES workspace_groups(id) ON DELETE CASCADE,
    pattern  TEXT NOT NULL,
    PRIMARY KEY (group_id, pattern)
);

CREATE TABLE IF NOT EXISTS api_key_groups (
    api_key_id TEXT NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE,
    group_id   TEXT NOT NULL REFERENCES workspace_groups(id) ON DELETE CASCADE,
    PRIMARY KEY (api_key_id, group_id)
);

CREATE INDEX IF NOT EXISTS idx_workspace_group_members_workspace ON workspace_group_members(workspace_id);
CREATE INDEX IF NOT EXISTS idx_api_key_groups_group ON api_key_groups(group_id);

-- Audit log: append-only record of mutations (docs/design/agent-pipeline.md §1,
-- plan 01a0bf7c). Every row is written after a successful mutation; audit
-- failures never block the mutation itself. The log outlives the data it
-- describes — standard retention cleanup never touches it (a dedicated audit
-- retention, default keep-forever, is the only pruner). Verbs are
-- dot-namespaced domain.action strings; actors are rendered at write time
-- (root, key <name>, agent <id>, system, migration) with the raw key id kept
-- alongside. No MCP read surface (decision 2026-09-20).
CREATE TABLE IF NOT EXISTS audit_log (
    id            TEXT PRIMARY KEY,
    workspace_id  TEXT,
    entity_type   TEXT NOT NULL,
    entity_id     TEXT NOT NULL,
    action        TEXT NOT NULL,
    actor         TEXT NOT NULL,
    actor_key_id  TEXT,
    via           TEXT NOT NULL DEFAULT '',
    notes         TEXT NOT NULL DEFAULT '',
    created_at    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_log(entity_type, entity_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_workspace ON audit_log(workspace_id, created_at);

-- Review fix 9: revision numbers are unique per plan; the read-then-insert
-- race in CreateRevision can no longer produce ambiguous LatestRevision
-- ordering (the constraint makes the loser fail loudly).
CREATE UNIQUE INDEX IF NOT EXISTS idx_plan_revisions_no ON plan_revisions(plan_id, revision_no);

-- Runs (agent-pipeline lean 1b): the job queue. A run is one stage of one
-- item's lifecycle (plan, implement, review, qa), claimed by exactly one
-- worker at a time. Affinity is a first-class property: a run interrupted
-- mid-flight re-claims to the worker that owns it (its session lives there);
-- another worker takes over only via resume_kind "branch" (fresh context
-- from the pushed branch). Stage routing is per-workspace config (which
-- runner each stage prefers); no tag engine, no capacity matrix.
CREATE TABLE IF NOT EXISTS runs (
    id               TEXT PRIMARY KEY,
    workspace_id     TEXT NOT NULL,
    item_id          TEXT NOT NULL,
    plan_rev_id      TEXT NOT NULL DEFAULT '',
    stage            TEXT NOT NULL,              -- plan | implement | review | qa
    runner           TEXT NOT NULL DEFAULT '',   -- the runner preference resolved at queue time
    worker_id        TEXT NOT NULL DEFAULT '',   -- affinity: the worker that claimed it
    status           TEXT NOT NULL,              -- queued|claimed|running|paused|succeeded|failed|interrupted|cancelled
    resume_kind      TEXT NOT NULL DEFAULT '',   -- session|branch (how a takeover may continue)
    lease_expires_at TEXT NOT NULL DEFAULT '',
    resume_after     TEXT NOT NULL DEFAULT '',   -- quota reset: a paused run past it is owner-reclaimable
    attempt          INTEGER NOT NULL DEFAULT 1,
    branch           TEXT NOT NULL DEFAULT '',
    base_sha         TEXT NOT NULL DEFAULT '',
    head_sha         TEXT NOT NULL DEFAULT '',
    result_summary   TEXT NOT NULL DEFAULT '',
    diffstat         TEXT NOT NULL DEFAULT '',
    checks           TEXT NOT NULL DEFAULT '[]',
    log_ref          TEXT NOT NULL DEFAULT '',
    fail_reason      TEXT NOT NULL DEFAULT '',
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_runs_queue ON runs(status, created_at);

-- Workers seen at claim time (registry-lite): what each worker OFFERS and
-- serves, recorded on every claim. Counts and live state stay derived from
-- runs; this is the capability record.
CREATE TABLE IF NOT EXISTS workers (
    id          TEXT PRIMARY KEY,
    runners     TEXT NOT NULL DEFAULT '[]',
    workspaces  TEXT NOT NULL DEFAULT '[]',
    last_seen   TEXT NOT NULL DEFAULT '',
    updated_at  TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_runs_item ON runs(item_id, created_at);
CREATE INDEX IF NOT EXISTS idx_runs_worker ON runs(worker_id, status);

-- Stage groups (tmp/multi-agent-stages — design.md §1): N runs of one stage
-- for one item, decided once by a recorded policy. Opt-in: a stage routed to
-- a single runner never creates a group. STRICT + CHECKs let SQLite reject
-- bad values; timestamps are Unix milliseconds (they sort exactly, unlike
-- RFC3339Nano text); NULL means "not yet".
CREATE TABLE IF NOT EXISTS run_groups (
    id            TEXT    PRIMARY KEY,
    workspace_id  TEXT    NOT NULL,
    item_id       TEXT    NOT NULL REFERENCES inbox_items(id) ON DELETE CASCADE,
    stage         TEXT    NOT NULL CHECK (stage IN ('plan', 'review', 'qa', 'branch_review')),
    round         INTEGER NOT NULL CHECK (round >= 1),
    size          INTEGER NOT NULL CHECK (size >= 2),
    policy        TEXT    NOT NULL CHECK (policy IN ('any-blocks', 'majority', 'all-pass', 'candidates')),
    early_exit    INTEGER NOT NULL DEFAULT 0 CHECK (early_exit IN (0, 1)),
    state         TEXT    NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'decided', 'cancelled')),
    outcome       TEXT    CHECK (outcome IN ('pass', 'fail', 'candidates', 'timeout')),
    base_sha      TEXT,
    deadline_ms   INTEGER NOT NULL,
    decided_ms    INTEGER,
    created_ms    INTEGER NOT NULL,
    CHECK ((state = 'decided') = (outcome IS NOT NULL)),
    CHECK ((state = 'open') = (decided_ms IS NULL)),
    UNIQUE (item_id, stage, round)
) STRICT;

-- One open group per item and stage, enforced by the database.
CREATE UNIQUE INDEX IF NOT EXISTS idx_run_groups_open ON run_groups(item_id, stage) WHERE state = 'open';
CREATE INDEX IF NOT EXISTS idx_run_groups_deadline ON run_groups(state, deadline_ms);

-- Run logs: what a run's agent, setup and checks printed, streamed by the
-- worker while it runs (POST /api/runs/{id}/log). One row per batch: the
-- batch's newline-delimited records, gzipped; seq is the readers' cursor.
-- bytes counts the uncompressed records (the per-run cap); rows past the
-- cleanup retention go (created_ms).
CREATE TABLE IF NOT EXISTS run_logs (
    seq           INTEGER PRIMARY KEY,
    run_id        TEXT    NOT NULL,
    workspace_id  TEXT    NOT NULL,
    created_ms    INTEGER NOT NULL,
    lines         INTEGER NOT NULL CHECK (lines >= 0),
    bytes         INTEGER NOT NULL CHECK (bytes >= 0),
    body          BLOB    NOT NULL
) STRICT;
CREATE INDEX IF NOT EXISTS idx_run_logs_run ON run_logs(run_id, seq);
CREATE INDEX IF NOT EXISTS idx_run_logs_created ON run_logs(created_ms);

-- Policy and configuration as append-only revisions (tmp/central-config —
-- design.md, phase 0; internal/confrev). A change is a new row; nothing
-- here is updated or deleted, so what applied on a given day can be shown
-- later. owner: "fleet:ceiling", "fleet:default", "group:<id>",
-- "workspace:<id>". config_heads points each owner at its current revision
-- (NULL = cleared).
CREATE TABLE IF NOT EXISTS config_revisions (
    id            TEXT    PRIMARY KEY,
    kind          TEXT    NOT NULL,
    owner         TEXT    NOT NULL,
    content       TEXT    NOT NULL CHECK (json_valid(content)),
    content_hash  TEXT    NOT NULL,
    created_ms    INTEGER NOT NULL,
    actor         TEXT    NOT NULL DEFAULT '',
    actor_key_id  TEXT    NOT NULL DEFAULT '',
    via           TEXT    NOT NULL DEFAULT '',
    note          TEXT    NOT NULL DEFAULT ''
) STRICT;
CREATE INDEX IF NOT EXISTS idx_config_revisions_owner ON config_revisions(kind, owner, created_ms);

CREATE TABLE IF NOT EXISTS config_heads (
    kind         TEXT    NOT NULL,
    owner        TEXT    NOT NULL,
    revision_id  TEXT,
    updated_ms   INTEGER NOT NULL,
    PRIMARY KEY (kind, owner)
) STRICT;

-- What applies to a workspace at a moment (tmp/central-config — design.md,
-- phase 2): rev names an ordered list of config_revisions (its groups', then
-- its own), so the config a run was claimed with can be read back after the
-- heads have moved on. Rows are written when a combination is first
-- resolved and never changed.
CREATE TABLE IF NOT EXISTS config_effective (
    rev           TEXT    PRIMARY KEY,
    workspace_id  TEXT    NOT NULL,
    parts         TEXT    NOT NULL CHECK (json_valid(parts)),
    created_ms    INTEGER NOT NULL
) STRICT;
CREATE INDEX IF NOT EXISTS idx_config_effective_ws ON config_effective(workspace_id, created_ms);

-- Stored secrets (tmp/central-config — design.md, phase 2b): the values of
-- the secrets a definition names (an MCP server's credentials), sealed
-- under the server's secret key and kept apart from the definition, which
-- holds names only. owner is what the secret belongs to
-- ("mcp_server:<name>"); key_id names the key that sealed the value
-- (internal/secretbox). Never read except to hand a run its servers.
CREATE TABLE IF NOT EXISTS secrets (
    owner       TEXT    NOT NULL,
    name        TEXT    NOT NULL,
    sealed      BLOB    NOT NULL,
    key_id      TEXT    NOT NULL,
    updated_ms  INTEGER NOT NULL,
    updated_by  TEXT    NOT NULL DEFAULT '',
    PRIMARY KEY (owner, name)
) STRICT;

-- Per-attempt run tokens (tmp/central-config — design.md, phase 0): the
-- hash of each token a claim mints. kind 'agent' is the credential the
-- run's agent reaches skopos with over MCP. A token is valid only while
-- its run is claimed or running with a live lease, read from the run
-- (internal/runs/tokens.go); ended_ms records when it stopped being so.
-- 'lease' and 'log' are reserved for the lease token and the run-log token.
CREATE TABLE IF NOT EXISTS run_tokens (
    token_hash  TEXT    PRIMARY KEY,
    run_id      TEXT    NOT NULL,
    attempt     INTEGER NOT NULL CHECK (attempt >= 1),
    kind        TEXT    NOT NULL CHECK (kind IN ('lease', 'agent', 'log')),
    issued_ms   INTEGER NOT NULL,
    ended_ms    INTEGER
) STRICT;
CREATE INDEX IF NOT EXISTS idx_run_tokens_run ON run_tokens(run_id, kind);
CREATE INDEX IF NOT EXISTS idx_run_tokens_open ON run_tokens(run_id) WHERE ended_ms IS NULL;

-- Pipeline settings (tmp/workspace-pipeline-settings — design.md): which
-- agents run each stage, per workspace or per workspace group. Resolution
-- per stage: the workspace's own row, else its group's, else not set.
-- owner_id names a workspace or a group id (two tables, so no FK; the
-- service drops rows of deleted owners). members is a JSON array of
-- {"runner","focus"}; a list is only valid on plan, review and qa.
CREATE TABLE IF NOT EXISTS pipeline_stages (
    owner_kind  TEXT    NOT NULL CHECK (owner_kind IN ('workspace', 'group')),
    owner_id    TEXT    NOT NULL,
    stage       TEXT    NOT NULL CHECK (stage IN ('plan', 'compare', 'synthesize', 'implement', 'review', 'qa')),
    members     TEXT    NOT NULL CHECK (json_valid(members) AND json_array_length(members) >= 1),
    policy      TEXT    CHECK (policy IS NULL OR policy IN ('any-blocks', 'majority', 'all-pass')),
    early_exit  INTEGER NOT NULL DEFAULT 0 CHECK (early_exit IN (0, 1)),
    timeout_ms  INTEGER CHECK (timeout_ms IS NULL OR timeout_ms > 0),
    updated_ms  INTEGER NOT NULL,
    updated_by  TEXT    NOT NULL,  -- API key id ('' = root, 'flag-import' = startup import)
    PRIMARY KEY (owner_kind, owner_id, stage)
) STRICT;

-- Owner-level pipeline defaults: what items without their own agents switch
-- get on a multi-agent stage (NULL = panel).
CREATE TABLE IF NOT EXISTS pipeline_defaults (
    owner_kind      TEXT    NOT NULL CHECK (owner_kind IN ('workspace', 'group')),
    owner_id        TEXT    NOT NULL,
    agents_default  TEXT    CHECK (agents_default IS NULL OR agents_default IN ('panel', 'solo')),
    second_opinion_runner TEXT,   -- default runner for on-demand second opinions (NULL = none)
    code_index      INTEGER CHECK (code_index IS NULL OR code_index IN (0, 1)), -- idle workers index this workspace (workspace owners only)
    updated_ms      INTEGER NOT NULL,
    updated_by      TEXT    NOT NULL,
    PRIMARY KEY (owner_kind, owner_id)
) STRICT;

-- Questions and answers (tmp/questions-and-answers — design.md): the record
-- of what the planner and the implementer asked and what the approver answered.
-- Append-only: rows are never updated or deleted (answers.used_by_run is
-- set once, phase 2). No foreign key to inbox_items: the record outlives a
-- deleted item. A set is one asking (every question one result returned);
-- n is the number steps cite. State (open, answered, answered in free text,
-- skipped, superseded) is derived from the rows (internal/qa).
CREATE TABLE IF NOT EXISTS questions (
    id            TEXT    PRIMARY KEY,
    workspace_id  TEXT    NOT NULL,
    item_id       TEXT    NOT NULL,
    set_id        TEXT    NOT NULL,
    n             INTEGER NOT NULL CHECK (n >= 1),
    asker         TEXT    NOT NULL CHECK (asker IN ('planner', 'implementer', 'worker')),
    stage         TEXT    NOT NULL DEFAULT '',
    run_id        TEXT,
    runner        TEXT    NOT NULL DEFAULT '',
    label         TEXT    NOT NULL DEFAULT '',
    subject_kind  TEXT    NOT NULL CHECK (subject_kind IN ('plan_revision', 'base', 'head', 'none')),
    subject       TEXT    NOT NULL DEFAULT '',
    blocking      INTEGER NOT NULL CHECK (blocking IN (0, 1)),
    text          TEXT    NOT NULL CHECK (text != ''),
    options       TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(options)),
    source        TEXT    NOT NULL CHECK (source IN ('worker', 'imported')),
    created_ms    INTEGER NOT NULL,
    UNIQUE (set_id, n)
) STRICT;
CREATE INDEX IF NOT EXISTS idx_questions_item ON questions(item_id, created_ms);
CREATE INDEX IF NOT EXISTS idx_questions_workspace ON questions(workspace_id, created_ms);

CREATE TABLE IF NOT EXISTS answers (
    id            TEXT    PRIMARY KEY,
    workspace_id  TEXT    NOT NULL,
    item_id       TEXT    NOT NULL,
    kind          TEXT    NOT NULL CHECK (kind IN ('answer', 'general', 'skipped')),
    question_id   TEXT    REFERENCES questions(id),
    set_id        TEXT,
    option        TEXT,
    text          TEXT    NOT NULL DEFAULT '',
    replaces      TEXT    REFERENCES answers(id),
    action        TEXT    NOT NULL CHECK (action IN ('approve', 'request_changes', 'retry', 'answer', 'imported')),
    approval_id   TEXT,
    actor         TEXT    NOT NULL,
    actor_key_id  TEXT,
    via           TEXT    NOT NULL DEFAULT '',
    used_by_run   TEXT,
    created_ms    INTEGER NOT NULL,
    CHECK (kind != 'answer'  OR (question_id IS NOT NULL AND (option IS NOT NULL OR text != ''))),
    CHECK (kind != 'skipped' OR question_id IS NOT NULL),
    CHECK (kind != 'general' OR (set_id IS NOT NULL AND question_id IS NULL AND text != ''))
) STRICT;
CREATE INDEX IF NOT EXISTS idx_answers_item ON answers(item_id, created_ms);
CREATE INDEX IF NOT EXISTS idx_answers_question ON answers(question_id);

-- Which version of the questions-and-answers import an item went through
-- (internal/qa ImportItem): 2 also records the answers given when no
-- question was open, which version 1 (v0.27.0) left out.
CREATE TABLE IF NOT EXISTS qa_imports (
    item_id  TEXT    PRIMARY KEY,
    version  INTEGER NOT NULL CHECK (version >= 1)
) STRICT;

-- Idempotency-Key (internal/idempotency): a POST's key, per API key, and
-- the response a retry gets back; pruned after 24 hours. status 0 = the
-- request is still running.
CREATE TABLE IF NOT EXISTS idempotency_keys (
    owner        TEXT NOT NULL,
    idem_key     TEXT NOT NULL,
    request_hash TEXT NOT NULL,
    status       INTEGER NOT NULL DEFAULT 0,
    content_type TEXT NOT NULL DEFAULT '',
    response     BLOB,
    created_ms   INTEGER NOT NULL,
    done_ms      INTEGER,
    PRIMARY KEY (owner, idem_key)
) STRICT;

CREATE INDEX IF NOT EXISTS idx_idempotency_created ON idempotency_keys(created_ms);

-- Integrations (internal/integrations, tmp/integrations — design.md §3):
-- every event another system may hear about, in write order. seq is the
-- feed cursor (AUTOINCREMENT: never reused, so a gap below the oldest row
-- means pruned events). data is the thin JSON payload.
CREATE TABLE IF NOT EXISTS integration_events (
    seq          INTEGER PRIMARY KEY AUTOINCREMENT,
    id           TEXT NOT NULL UNIQUE,
    type         TEXT NOT NULL,
    workspace_id TEXT NOT NULL DEFAULT '',
    item_id      TEXT NOT NULL DEFAULT '',
    occurred_ms  INTEGER NOT NULL,
    data         TEXT NOT NULL CHECK (json_valid(data))
) STRICT;

CREATE INDEX IF NOT EXISTS idx_integration_events_occurred ON integration_events(occurred_ms);

-- Webhook subscriptions. Secrets are encrypted with the server's
-- integrations key (they must be readable to sign). cursor_seq is the last
-- event fanned out; failing_since_ms starts a run of failed attempts (a
-- success, or 12 hours without a failed attempt, ends it; a run of 3 days
-- disables the subscription); last_failure_ms is its newest failure.
CREATE TABLE IF NOT EXISTS webhooks (
    id               TEXT PRIMARY KEY,
    name             TEXT NOT NULL,
    url              TEXT NOT NULL,
    workspaces       TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(workspaces)),
    groups           TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(groups)),
    types            TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(types)),
    secret_enc       BLOB NOT NULL,
    old_secret_enc   BLOB,
    old_until_ms     INTEGER,
    enabled          INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    disabled_reason  TEXT NOT NULL DEFAULT '',
    failing_since_ms INTEGER,
    last_failure_ms  INTEGER,
    cursor_seq       INTEGER NOT NULL DEFAULT 0,
    created_by       TEXT NOT NULL,
    created_ms       INTEGER NOT NULL,
    updated_ms       INTEGER NOT NULL
) STRICT;

-- One event to one subscription: state pending | delivered | failed;
-- attempts counts this schedule's tries (a redelivery starts a new one).
CREATE TABLE IF NOT EXISTS webhook_deliveries (
    id           TEXT PRIMARY KEY,
    webhook_id   TEXT NOT NULL REFERENCES webhooks(id) ON DELETE CASCADE,
    event_seq    INTEGER NOT NULL,
    item_id      TEXT NOT NULL DEFAULT '',
    state        TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'delivered', 'failed')),
    attempts     INTEGER NOT NULL DEFAULT 0,
    next_ms      INTEGER NOT NULL,
    last_code    INTEGER NOT NULL DEFAULT 0,
    last_error   TEXT NOT NULL DEFAULT '',
    last_ms      INTEGER,
    created_ms   INTEGER NOT NULL,
    UNIQUE (webhook_id, event_seq)
) STRICT;

CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_due ON webhook_deliveries(state, next_ms);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_hook ON webhook_deliveries(webhook_id, event_seq);

-- Every attempt, for the deliveries log.
CREATE TABLE IF NOT EXISTS webhook_attempts (
    delivery_id TEXT NOT NULL REFERENCES webhook_deliveries(id) ON DELETE CASCADE,
    at_ms       INTEGER NOT NULL,
    code        INTEGER NOT NULL DEFAULT 0,
    error       TEXT NOT NULL DEFAULT '',
    duration_ms INTEGER NOT NULL DEFAULT 0
) STRICT;

CREATE INDEX IF NOT EXISTS idx_webhook_attempts_delivery ON webhook_attempts(delivery_id, at_ms);
